  "inlineSchema": "// ============================================================\n// SALON BOOKING PLATFORM — DATABASE SCHEMA\n// ============================================================\n// Read this file top to bottom — it IS the data model.\n// Run `npx prisma migrate dev` after editing this to update your DB.\n// ============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ------------------------------------------------------------\n// ROLES\n// ------------------------------------------------------------\n// One User table for everyone. The `role` field decides what\n// they can do. This is simpler than separate tables per role,\n// and is what the RBAC middleware checks against.\nenum Role {\n  CUSTOMER\n  STAFF\n  SALON_OWNER\n  ADMIN\n}\n\nenum AppointmentStatus {\n  BOOKED\n  CANCELLED\n  COMPLETED\n  NO_SHOW\n}\n\n// ------------------------------------------------------------\n// USER — every person in the system, regardless of role\n// ------------------------------------------------------------\nmodel User {\n  id           String   @id @default(uuid())\n  name         String\n  email        String   @unique\n  passwordHash String\n  phone        String?\n  role         Role     @default(CUSTOMER)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  // Relations\n  salonsOwned  Salon[]       @relation(\"SalonOwner\")\n  staffProfile Staff? // only present if role = STAFF\n  appointments Appointment[] @relation(\"CustomerAppointments\")\n  reviews      Review[]\n\n  @@map(\"users\")\n}\n\n// ------------------------------------------------------------\n// SALON — a tenant. Each salon has its own services/staff/hours.\n// ------------------------------------------------------------\nmodel Salon {\n  id          String   @id @default(uuid())\n  ownerId     String\n  owner       User     @relation(\"SalonOwner\", fields: [ownerId], references: [id])\n  name        String\n  description String?\n  address     String\n  city        String\n  latitude    Float?\n  longitude   Float?\n  phone       String?\n  imageUrl    String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  services     Service[]\n  staff        Staff[]\n  appointments Appointment[]\n  reviews      Review[]\n\n  @@map(\"salons\")\n}\n\n// ------------------------------------------------------------\n// SERVICE CATEGORY — e.g. \"Hair\", \"Nails\", \"Spa\" (used by admin)\n// ------------------------------------------------------------\nmodel ServiceCategory {\n  id       String    @id @default(uuid())\n  name     String    @unique\n  services Service[]\n\n  @@map(\"service_categories\")\n}\n\n// ------------------------------------------------------------\n// SERVICE — belongs to one salon\n// ------------------------------------------------------------\nmodel Service {\n  id              String           @id @default(uuid())\n  salonId         String\n  salon           Salon            @relation(fields: [salonId], references: [id], onDelete: Cascade)\n  categoryId      String?\n  category        ServiceCategory? @relation(fields: [categoryId], references: [id])\n  name            String\n  description     String?\n  durationMinutes Int // used to compute slot length\n  price           Decimal          @db.Decimal(10, 2)\n  isActive        Boolean          @default(true)\n  createdAt       DateTime         @default(now())\n\n  staff        StaffService[]\n  appointments Appointment[]\n\n  @@map(\"services\")\n}\n\n// ------------------------------------------------------------\n// STAFF — a User with role=STAFF, linked to one salon\n// ------------------------------------------------------------\nmodel Staff {\n  id        String   @id @default(uuid())\n  userId    String   @unique\n  user      User     @relation(fields: [userId], references: [id])\n  salonId   String\n  salon     Salon    @relation(fields: [salonId], references: [id], onDelete: Cascade)\n  bio       String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  services     StaffService[]\n  workingHours WorkingHour[]\n  leaves       Leave[]\n  appointments Appointment[]\n\n  @@map(\"staff\")\n}\n\n// Many-to-many: which services a staff member can perform\nmodel StaffService {\n  staffId   String\n  staff     Staff   @relation(fields: [staffId], references: [id], onDelete: Cascade)\n  serviceId String\n  service   Service @relation(fields: [serviceId], references: [id], onDelete: Cascade)\n\n  @@id([staffId, serviceId])\n  @@map(\"staff_services\")\n}\n\n// ------------------------------------------------------------\n// WORKING HOURS — recurring weekly schedule per staff member\n// ------------------------------------------------------------\nmodel WorkingHour {\n  id        String @id @default(uuid())\n  staffId   String\n  staff     Staff  @relation(fields: [staffId], references: [id], onDelete: Cascade)\n  dayOfWeek Int // 0 = Sunday ... 6 = Saturday\n  startTime String // \"09:00\" (24hr, stored as string for simplicity)\n  endTime   String // \"18:00\"\n\n  @@map(\"working_hours\")\n}\n\n// ------------------------------------------------------------\n// LEAVE — time off / unavailable dates for a staff member\n// ------------------------------------------------------------\nmodel Leave {\n  id        String   @id @default(uuid())\n  staffId   String\n  staff     Staff    @relation(fields: [staffId], references: [id], onDelete: Cascade)\n  startDate DateTime\n  endDate   DateTime\n  reason    String?\n\n  @@map(\"leaves\")\n}\n\n// ------------------------------------------------------------\n// APPOINTMENT — the booking itself\n// ------------------------------------------------------------\n// startTime/endTime are the ACTUAL guard against double-booking.\n// See the @@index below — we query by (staffId, startTime, endTime)\n// constantly, so it needs to be fast AND we wrap the create in a\n// transaction in the controller to prevent race conditions.\nmodel Appointment {\n  id         String            @id @default(uuid())\n  customerId String\n  customer   User              @relation(\"CustomerAppointments\", fields: [customerId], references: [id])\n  salonId    String\n  salon      Salon             @relation(fields: [salonId], references: [id])\n  staffId    String\n  staff      Staff             @relation(fields: [staffId], references: [id])\n  serviceId  String\n  service    Service           @relation(fields: [serviceId], references: [id])\n  startTime  DateTime\n  endTime    DateTime\n  status     AppointmentStatus @default(BOOKED)\n  notes      String?\n  createdAt  DateTime          @default(now())\n  updatedAt  DateTime          @updatedAt\n\n  review Review?\n\n  @@index([staffId, startTime, endTime])\n  @@map(\"appointments\")\n}\n\n// ------------------------------------------------------------\n// REVIEW — one review per completed appointment\n// ------------------------------------------------------------\nmodel Review {\n  id            String      @id @default(uuid())\n  appointmentId String      @unique\n  appointment   Appointment @relation(fields: [appointmentId], references: [id])\n  customerId    String\n  customer      User        @relation(fields: [customerId], references: [id])\n  salonId       String\n  salon         Salon       @relation(fields: [salonId], references: [id])\n  rating        Int // 1-5\n  comment       String?\n  createdAt     DateTime    @default(now())\n\n  @@map(\"reviews\")\n}\n",
